#!/usr/bin/env python3
"""Build an offline, self-contained screenshot gallery from captured page images."""
import base64
import html
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
pages = json.loads((root / 'screenshots/full-site/pages.json').read_text())
cards = []
nav = []
for i, p in enumerate(pages):
    image = root / 'screenshots/full-site' / (p['id'] + '.jpg')
    data = base64.b64encode(image.read_bytes()).decode()
    title, route, group = map(html.escape, (p['title'], p['path'], p['group']))
    nav.append(f'<a href="#page-{p["id"]}"><span>{title}</span><small>{group}</small></a>')
    cards.append(f'''<article id="page-{p['id']}" class="page-card" data-group="{group}" data-search="{title} {route}">
      <div class="card-header"><div><span>{group}</span><h2>{title}</h2></div><a href="index.html#{p.get('target',p['id'])}" target="_blank" rel="noopener">打开原型 ↗</a></div>
      <button class="image-button" data-index="{i}" aria-label="放大{title}截图"><img src="data:image/jpeg;base64,{data}" alt="{title}完整渲染截图" loading="lazy" width="1600" height="1100"></button>
      <footer><span>{route}</span><button data-index="{i}">放大查看 ⤢</button></footer>
    </article>''')
groups = list(dict.fromkeys(p['group'] for p in pages))
filters = ''.join(f'<option>{html.escape(g)}</option>' for g in groups)
source = '''<!doctype html>
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>RoboMark · 全站 UI 截图总览</title>
<style>
:root{--bg:#f7f8fa;--paper:#fff;--ink:#20232c;--muted:#747b89;--line:#e9ebef;--blue:#3a61ed}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:120px}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;color:var(--ink);background:var(--bg);font-size:14px}a{color:inherit;text-decoration:none}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #8da7ff;outline-offset:3px}.layout{display:grid;grid-template-columns:232px minmax(0,1fr)}aside{height:100vh;position:sticky;top:0;border-right:1px solid var(--line);background:#fcfcfd;padding:29px 18px;overflow-y:auto}.brand{font-size:21px;font-weight:700;letter-spacing:-.7px;display:flex;gap:10px;align-items:center;padding:0 10px}.brand b{background:#273149;color:white;border-radius:7px;font-size:17px;width:29px;height:29px;display:grid;place-items:center}.brand em{color:var(--blue);font-style:normal}.nav-label{font-size:11px;color:#a0a7b4;margin:29px 12px 13px}nav{display:flex;flex-direction:column;gap:3px}nav a{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 12px;border-radius:6px;font-size:12px;color:#68778c}nav a:hover{color:var(--blue);background:#edf1fe}nav small{font-size:9px;color:#a6afbe}.aside-note{margin:25px 12px 0;font-size:10px;line-height:1.9;color:#9ba5b5}.main{min-width:0}.topbar{height:68px;position:sticky;top:0;z-index:3;background:#fff;border-bottom:1px solid var(--line);padding:0 32px;display:flex;align-items:center;gap:14px;font-size:12px;color:#8c96a6}.topbar strong{font-weight:500;color:#46546b}.spacer{flex:1}.topbar a{padding:9px 12px;border:1px solid #dfe4ed;border-radius:6px;color:#52678f}.status{display:flex;gap:6px;align-items:center;font-size:10px}.status i{width:6px;height:6px;border-radius:50%;background:#719c88}.content{max-width:2000px;margin:auto;padding:34px 32px}.intro{display:flex;align-items:flex-start;gap:25px;justify-content:space-between}.intro h1{font-size:30px;letter-spacing:-1px;font-weight:600;margin:0 0 12px}.intro p{font-size:12px;line-height:1.9;color:#8893a4;margin:0}.intro-meta{padding:12px 16px;background:#eef2fb;color:#7085ac;border-radius:7px;font-size:11px;line-height:1.8;flex:none}.controls{display:flex;align-items:center;gap:12px;margin:28px 0 23px}.search{display:flex;gap:9px;align-items:center;background:white;border:1px solid #e0e5ed;border-radius:7px;padding:9px 12px;color:#94a0b3}.search input{width:200px;background:none;border:0;outline:none;font-size:12px;color:#5c6b82}.search input::placeholder{color:#a3acb9}select{border:1px solid #e0e5ed;background:white;border-radius:7px;padding:9px 12px;color:#79879d;font-size:12px}.layout-buttons{display:flex;gap:3px;background:#e9edf4;padding:3px;border-radius:7px}.layout-buttons button{background:transparent;border:0;padding:6px 12px;color:#8591a6;border-radius:4px;font-size:11px}.layout-buttons button.active{background:white;color:#3d5fbb}.count{color:#99a3b3;font-size:11px}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:25px}.gallery.single{grid-template-columns:1fr}.page-card{background:white;border:1px solid var(--line);border-radius:10px;overflow:hidden;min-width:0;scroll-margin-top:95px}.page-card[hidden]{display:none}.card-header{display:flex;align-items:center;justify-content:space-between;padding:19px 20px;gap:15px}.card-header span{font-size:10px;color:#9aa5b6}.card-header h2{font-size:15px;font-weight:550;margin:7px 0 0}.card-header a{font-size:11px;color:#7186b0;white-space:nowrap}.image-button{display:block;width:100%;border:0;background:#edf0f5;padding:0;overflow:hidden}.image-button img{display:block;width:100%;height:auto;aspect-ratio:auto;object-fit:contain;transition:opacity .2s}.image-button:hover img{opacity:.85}.page-card footer{display:flex;align-items:center;justify-content:space-between;padding:12px 17px;gap:12px;color:#9aa5b6;font-size:10px}.page-card footer>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.page-card footer>button{color:#8598bc;background:transparent;border:0;font-size:10px;white-space:nowrap}.empty{padding:50px;text-align:center;color:#8f9bb0}.foot{display:flex;justify-content:space-between;gap:20px;margin-top:30px;color:#a5afbd;font-size:10px;line-height:1.8}dialog{padding:0;border:1px solid #d6deeb;border-radius:10px;max-width:96vw;width:1660px;max-height:95vh;background:#eef1f7;color:#4c5e79;box-shadow:0 25px 90px #0c1a3d50}dialog::backdrop{background:#111b30c9}.viewer-header{position:sticky;top:0;display:flex;gap:12px;align-items:center;background:white;padding:13px 18px;z-index:2}.viewer-header h2{font-size:14px;margin:0}.viewer-header button{border:1px solid #dde4f0;background:white;border-radius:5px;padding:7px 12px;font-size:11px;color:#6e809f}.viewer-header button.active{background:#eaf0ff;color:#3a61ed}.viewer-header a{font-size:11px;color:#6f86b2}.viewer-body{overflow:auto;max-height:calc(95vh - 58px)}.viewer-body img{display:block;width:100%;height:auto;margin:auto}.viewer-body.original img{width:1600px;max-width:none}.viewer-footer{font-size:10px;color:#94a2b7;background:white;padding:9px 18px}body:has(dialog[open]){overflow:hidden}@media(min-width:1800px){.gallery{gap:30px}.content{padding:40px}}@media(max-width:1100px){.layout{grid-template-columns:190px 1fr}.content{padding:26px 22px}.topbar{padding:0 22px}.intro-meta{display:none}.gallery{gap:18px}.card-header{padding:15px}.card-header h2{font-size:13px}.card-header a{font-size:10px}.search input{width:150px}.controls{flex-wrap:wrap}.controls .spacer{display:none}.count{margin-left:auto}.gallery{grid-template-columns:1fr}}@media(max-width:700px){.layout{display:block}aside{display:none}.topbar{height:57px;padding:0 17px;gap:8px}.topbar>.status,.topbar>.crumb{display:none}.topbar>a{font-size:10px}.content{padding:25px 16px}.intro h1{font-size:26px}.intro p{font-size:11px}.controls{gap:9px}.search{flex:1;min-width:170px}.search input{width:100%;min-width:0}.controls select{max-width:110px;font-size:11px}.layout-buttons{display:none}.count{width:100%;margin-top:5px}.card-header{padding:16px}.card-header h2{font-size:14px}.foot{font-size:9px}.viewer-header{flex-wrap:wrap;gap:8px;padding:10px 12px}.viewer-header h2{font-size:12px}.viewer-header button{padding:6px 9px;font-size:10px}.viewer-header>a{display:none}.viewer-body{max-height:calc(95vh - 95px)}dialog{max-width:98vw}.viewer-footer{font-size:9px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}@media print{aside,.topbar,.controls,dialog,.card-header>a,.page-card footer button{display:none}.layout{display:block}.content{padding:0}.gallery{display:block}.page-card{break-inside:avoid;margin:20px 0}.intro{margin-bottom:20px}}
</style></head><body><div class="layout"><aside><a class="brand" href="#"><b>⌁</b><span>RoboMark<em>.</em></span></a><div class="nav-label">全站页面 · __COUNT__</div><nav>__NAV__</nav><p class="aside-note">延续原三页原型的浅色管理界面与深色画布。<br>所有截图均嵌入本 HTML，可离线查看。</p></aside><main class="main"><header class="topbar"><strong>RoboMark UI</strong><span class="crumb">/ 全站截图总览</span><span class="spacer"></span><span class="status"><i></i>__COUNT__ 个画面已渲染</span><a href="index.html#home">体验交互原型 ↗</a></header><div class="content"><div class="intro"><div><h1>同一种设计，每一处体验。</h1><p>修订区域以红框标记。包含完整页面与新增弹窗，统一预览。<br>点击截图可放大，使用左右方向键切换页面，按 Esc 退出。</p></div><div class="intro-meta">2026.10.21 · 全站设计原型<br>桌面截图 1600 × 1100 · 完整页面</div></div><div class="controls"><label class="search">⌕<input id="search" type="search" placeholder="搜索页面或路由…" aria-label="搜索页面"></label><select id="group" aria-label="按页面分组"><option value="all">全部页面</option>__FILTERS__</select><span class="spacer"></span><span class="count" id="count">__COUNT__ / __COUNT__ 个画面</span><div class="layout-buttons"><button data-layout="double" class="active">双列总览</button><button data-layout="single">单列细看</button></div></div><div class="gallery" id="gallery">__CARDS__</div><p class="empty" id="empty" hidden>没有匹配的页面，换个关键词试试。</p><footer class="foot"><span>RoboMark · AIM Team, UNNC</span><span>设计原型 · 业务数据均为示例<br>影像参考 MVM3D · MIT License</span></footer></div></main></div><dialog id="viewer" aria-labelledby="viewer-title"><header class="viewer-header"><h2 id="viewer-title"></h2><span class="spacer"></span><a id="viewer-link" target="_blank" rel="noopener">打开交互原型 ↗</a><button id="prev" aria-label="上一个页面">←</button><button id="next" aria-label="下一个页面">→</button><button id="zoom">原始尺寸</button><button id="close" aria-label="关闭放大预览">关闭 ✕</button></header><div class="viewer-body"><img id="viewer-image" alt=""></div><footer class="viewer-footer">← → 切换页面 · Esc 关闭 · 红框为本次修订 · 截图是静态画面，交互请打开原型</footer></dialog>
<script>
const cards=[...document.querySelectorAll('.page-card')],viewer=document.querySelector('#viewer');let current=0;
function filter(){let count=0;const q=document.querySelector('#search').value.trim().toLowerCase(),g=document.querySelector('#group').value;cards.forEach(card=>{card.hidden=!(card.dataset.search.toLowerCase().includes(q)&&(g==='all'||card.dataset.group===g));if(!card.hidden)count++});document.querySelector('#count').textContent=count+' / '+cards.length+' 个画面';document.querySelector('#empty').hidden=!!count}
document.querySelector('#search').addEventListener('input',filter);document.querySelector('#group').addEventListener('change',filter);
function show(index){current=(index+cards.length)%cards.length;const card=cards[current],img=card.querySelector('img'),target=document.querySelector('#viewer-image');target.src=img.src;target.alt=img.alt;document.querySelector('#viewer-title').textContent=card.querySelector('h2').textContent+' · '+(current+1)+' / '+cards.length;document.querySelector('#viewer-link').href=card.querySelector('a').href;document.querySelector('.viewer-body').scrollTo(0,0);if(!viewer.open)viewer.showModal()}
document.querySelectorAll('[data-index]').forEach(b=>b.addEventListener('click',()=>show(+b.dataset.index)));document.querySelector('#close').onclick=()=>viewer.close();document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#zoom').onclick=()=>{const original=document.querySelector('.viewer-body').classList.toggle('original');document.querySelector('#zoom').textContent=original?'适应宽度':'原始尺寸';document.querySelector('#zoom').classList.toggle('active',original)};document.addEventListener('keydown',e=>{if(!viewer.open)return;if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}});viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{document.querySelector('#gallery').classList.toggle('single',b.dataset.layout==='single');document.querySelectorAll('[data-layout]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#search').value='';document.querySelector('#group').value='all';filter()}));
</script></body></html>'''
source = source.replace('__COUNT__', str(len(pages)))
source = source.replace('__NAV__', ''.join(nav)).replace('__FILTERS__', filters).replace('__CARDS__', '\n'.join(cards))
(root / 'gallery.html').write_text(source)
print(f'Built gallery.html: {len(pages)} embedded screenshots, {len(source.encode()) / 1024 / 1024:.1f} MB')
